import {writingTipHTML} from './wise-help.js';
import {createPhrasebookUI} from './phrasebook.js';
export function createTeachingUI({api,esc,heading,list,toast,modal,isCurrent}) {
 const $=s=>document.querySelector(s);
 const phrasebook=createPhrasebookUI({api,esc,toast,isCurrent});
 const readLocal=key=>{try{return localStorage.getItem(key)||''}catch{return ''}};
 const putLocal=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
 let selectedQuote='';

 function flag(context=location.hash,quote=selectedQuote||window.getSelection()?.toString()||'') {
  const cache='awl-flag-draft-'+context;
  let saved={};try{saved=JSON.parse(readLocal(cache)||'{}')}catch{}
  modal('Flag unclear wording',`<p>Select wording on the page before opening this form, or paste it below. Add what you expected or what you cannot understand.</p><p class="tiny">Attached to: ${esc(context)}</p><label class="field">Wording to discuss<textarea id="flag-quote" rows="3" maxlength="4000"></textarea></label><label class="field">What is unclear?<textarea id="flag-comment" rows="4" maxlength="4000" placeholder="For example: I understand the two ideas, but not what the missing reason should explain."></textarea></label><button class="btn" id="save-flag">Save my comment</button><p id="flag-status" role="status"></p><p class="tiny">Saved locally in the lab and included in backups. This does not send a message to a supervisor or automatically change the exercise.</p>`);
  $('#flag-quote').value=quote.slice(0,4000)||saved.quote||'';$('#flag-comment').value=saved.comment||'';
  const cacheDraft=()=>putLocal(cache,JSON.stringify({quote:$('#flag-quote').value,comment:$('#flag-comment').value}));
  $('#flag-quote').oninput=cacheDraft;$('#flag-comment').oninput=cacheDraft;
  $('#save-flag').onclick=async()=>{const b=$('#save-flag');b.disabled=true;try{await api('/wording-flags',{context,quote:$('#flag-quote').value,comment:$('#flag-comment').value});putLocal(cache,'');selectedQuote='';$('#modal').close();toast('Comment saved. Find it in My comments.')}catch(e){$('#flag-status').textContent=e.message;b.disabled=false}};
  $('#flag-comment').focus();
 }
 function bindFlagButton(){
  const b=$('#flag-wording');
  b.onpointerdown=()=>{selectedQuote=window.getSelection()?.toString()||''};
  b.onclick=()=>flag();
 }

 async function enhancePractice(e,context,isActive){
  const r=await api('/teaching/exercises/'+encodeURIComponent(e.key));if(!isActive())return;
  const example=r.example,help=r.task_help,anchor=$('.exercise-body .prompt');
  anchor.insertAdjacentHTML('beforebegin',`<section class="learning-support" aria-label="Help understanding the exercise"><h3>What should I write?</h3><p>${esc(r.output_note)}</p>${help?`<details class="task-steps"><summary>Step by step</summary><ol>${help.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></details>${help.terms.length?`<details class="terms-panel" ${help.terms.some(t=>['actor','referent'].includes(t.term))?'open':''}><summary>Words in this task, explained (${help.terms.length})</summary>${help.terms.filter(t=>['actor','referent'].includes(t.term)).map(t=>`<details class="term-help" ${['actor','referent'].includes(t.term)?'open':''}><summary>${esc(t.term)}</summary><p>${esc(t.meaning)}</p><p class="tiny"><strong>Example:</strong> ${esc(t.example)}</p></details>`).join('')}<details class="more-terms"><summary>More writing terms and examples</summary>${help.terms.filter(t=>!['actor','referent'].includes(t.term)).map(t=>`<details class="term-help"><summary>${esc(t.term)}</summary><p>${esc(t.meaning)}</p><p class="tiny"><strong>Example:</strong> ${esc(t.example)}</p></details>`).join('')}</details></details>`:''}`:''}${e.reading?`<p class="tiny"><strong>${esc(e.task_type)} · ${e.estimated_minutes} minutes suggested</strong> · <a href="/api/paper/readings/${encodeURIComponent(e.reading.book_id)}#page=${Math.max(1,Number(e.reading.page)||1)}" target="_blank" rel="noreferrer">Read the principle · ${esc(e.reading.title)}, PDF p. ${e.reading.page}–${e.reading.end_page}</a></p>`:''}${!r.tailored?'<p class="tiny">This is a general format illustration for this imported exercise. Follow its specific prompt below.</p>':''}<button class="btn secondary" id="cross-domain-example">See an example from ${esc(example.subject.toLowerCase())}</button><div id="cross-domain-worked" hidden></div>${r.bridge_ideas.length?`<details id="bridge-planner" open><summary>Build the missing reasoning step by step</summary><p><strong>Write only the linking explanation: one or two sentences.</strong> First identify the two ideas. Then explain the reason connecting them.</p><div class="bridge-fields"><label class="field">Idea A<select id="bridge-a">${r.bridge_ideas.map((x,i)=>`<option value="${i}">${esc(x)}</option>`).join('')}</select></label><label class="field">Idea B<select id="bridge-b">${r.bridge_ideas.map((x,i)=>`<option value="${i}" ${i===2?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="field">Why does A support or qualify B?<textarea id="bridge-reason" rows="3" placeholder="Name the consequence, need or assumption that connects these two ideas."></textarea></label><label class="field">What must not be inferred? (optional)<textarea id="bridge-limit" rows="2" placeholder="What remains unknown, or needs another check?"></textarea></label></div><p class="tiny">These planning notes stay in this browser. Write your final bridge in Your answer below, or explicitly copy your own reason there.</p><button class="btn quiet" id="bridge-use">Copy my reason into an empty answer</button><p id="bridge-status" role="status"></p></details>`:''}</section>`);
  let viewed=false;
  $('#cross-domain-example').onclick=async()=>{
   const area=$('#cross-domain-worked');if(!area.hidden){area.hidden=true;$('#cross-domain-example').textContent='See an example from '+example.subject.toLowerCase();return}
   try{if(!viewed){await api('/teaching/view',{session_id:context.session.id});viewed=true}if(!isActive())return;
    area.innerHTML=`<h3>A worked example from another subject</h3><p>${esc(example.task)}</p><p class="tiny">${esc(example.provenance)} Longer examples demonstrate structure; follow the word range in your own task.</p><div class="worked-answer prose">${esc(example.answer)}</div><h4>Why this works</h4><ol>${example.moves.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p><strong>Your turn:</strong> ${esc(example.transfer)}</p><p class="tiny">This example is available from the start. Viewing it is recorded separately from your answers. It is not the accepted answer to the exercise below.</p>`;area.hidden=false;$('#cross-domain-example').textContent='Hide the worked example';
   }catch(err){toast(err.message)}
  };
  if(r.bridge_ideas.length){
   const key=context.cache+'-bridge';let notes={};try{notes=JSON.parse(readLocal(key)||'{}')}catch{}
   for(const id of ['a','b','reason','limit']){const el=$('#bridge-'+id);if(notes[id]!==undefined)el.value=notes[id];el.oninput=()=>{notes=Object.fromEntries(['a','b','reason','limit'].map(k=>[k,$('#bridge-'+k).value]));putLocal(key,JSON.stringify(notes));$('#bridge-status').textContent=notes.a===notes.b?'Choose two different ideas.':'Planning notes kept in this browser.'}}
   $('#bridge-use').onclick=()=>{if($('#bridge-a').value===$('#bridge-b').value){$('#bridge-status').textContent='Choose two different ideas first.';return}if($('#answer').value.trim()){$('#bridge-status').textContent='Your answer already contains text. Copy the part you want manually so you keep your existing writing.';return}const reason=$('#bridge-reason').value.trim();if(!reason){$('#bridge-status').textContent='Write your own reason first.';return}$('#answer').value=[reason,$('#bridge-limit').value.trim()].filter(Boolean).join(' ');$('#answer').dispatchEvent(new Event('input'));$('#answer').focus();$('#bridge-status').textContent='Your own planning text is now in the answer. Edit it, then submit.'};
  }
 }

 async function toolbox(nodeId,container,isActive=()=>true){
  const r=await api('/teaching/toolbox'+(nodeId?'?node_id='+encodeURIComponent(nodeId):''));if(!isActive()||!container.isConnected)return;
  container.innerHTML=`<h2>Build the argument in clear English</h2>${r.reader_question?`<p class="reader-question"><strong>The reader’s question:</strong> ${esc(r.reader_question)}</p>`:''}<details open><summary>Plan this paragraph</summary><ol>${r.plan.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="tiny">Use the moves this paragraph needs. This is a planning aid, not a fixed sentence formula.</p></details><details><summary>Useful vocabulary for this part of WISE</summary><div class="table-wrap"><table><thead><tr><th>Expression</th><th>Use it to mean</th><th>Meaning to protect</th></tr></thead><tbody>${r.vocabulary.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><details><summary>Sentence patterns: although, because, therefore and bridges</summary><p>Choose the logical relation first, then its wording. All examples below are constructed.</p><div class="table-wrap"><table><thead><tr><th>Relation</th><th>Pattern</th><th>Everyday example</th><th>Check</th></tr></thead><tbody>${r.patterns.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><details><summary>Academic English without inflated prose</summary>${list(r.rules)}</details><details><summary>Sources to learn from</summary><p>The patterns above are original examples. These university resources explain the underlying writing principles; the book links below the paragraph brief give your focused readings.</p>${r.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)}</a><br><span class="tiny">${esc(s.use)}</span></p>`).join('')}</details><p><a href="#reader">Read the critical WISE card reviews</a> · <button class="btn quiet" id="flag-brief">Flag unclear wording in this brief</button></p>`;
  $('#flag-brief').onclick=()=>flag();
 }

 const verdicts={clear:'Reads clearly',needs_clarification:'Clarify the meaning',needs_revision:'Revise the claim or wording',not_prose:'Non-prose material'};
 function reviewHTML(r){
  if(!r.available)return '<p>This card has no reader review yet.</p>';
  return `${r.stale?'<div class="alert error">This review belongs to an older imported version. Recheck the quotations and conclusions before using it.</div>':''}<p><span class="tag">${esc(verdicts[r.verdict])}</span></p><h3>What the reader understands</h3><p>${esc(r.intended_meaning)}</p>${r.reader_question?`<h3>Question for you, the author</h3><p class="reader-question">${esc(r.reader_question)}</p>`:''}${r.findings.length?'<h3>Specific points to check</h3>'+r.findings.map(f=>`<div class="issue"><span class="tag neutral">${esc(f.severity)} · ${esc(f.category)}</span><blockquote class="prose">${esc(f.quote)}</blockquote><p>${esc(f.explanation)}</p><p><strong>Your revision task:</strong> ${esc(f.revision_task)}</p></div>`).join(''):'<p>No specific defect was identified in this reading. This does not verify the cited evidence or empirical results.</p>'}<h3>In its surrounding argument</h3><p>${esc(r.contextual_note)}</p><p class="tiny">${esc(r.reviewer_role)} · AI review of the imported source card. Scientific judgements are questions to check, not supervisor decisions. Original text is preserved.</p>`;
 }
 async function reader(id,serial){
  if(id){
   const [r,c]=await Promise.all([api('/reader-reviews/'+encodeURIComponent(id)),api('/paper/cards/'+encodeURIComponent(id))]);if(!isCurrent(serial))return;
   $('#main').innerHTML=heading(c.id,'Read what the paragraph communicates, then decide which ideas to keep.', '<a class="btn secondary" href="#reader">All WISE card reviews</a>')+`<section class="card">${reviewHTML(r)}<details><summary>Original card text and context</summary><pre class="source-text">${esc(c.raw)}</pre></details><p class="tiny">${esc(c.archive_path)} · ${c.in_paper?'Marked as used in the archive':'Alternative in the archive'} · Imported source snapshot, not a newly written learner paragraph.</p><div id="reader-target-help"></div><button class="btn secondary" id="flag-review">Record my question or disagreement</button></section>`;
   const support=await api('/revision/card-support/'+encodeURIComponent(id));if(!isCurrent(serial))return;let returnTarget='I-06';try{returnTarget=JSON.parse(localStorage.getItem('awl-writing-resume'))||returnTarget}catch{};$('#reader-target-help').innerHTML=`<h3>Targeted language help for this source card</h3><p class="tiny">${esc(support.scope)}</p>${support.tips.map(t=>writingTipHTML(t,returnTarget,esc)).join('')}<a href="#paper/${esc(returnTarget)}">Return to WISE · ${esc(returnTarget)}</a>`;
   $('#flag-review').onclick=()=>flag();return;
  }
  const r=await api('/reader-reviews');if(!isCurrent(serial))return;let page=0;
  $('#main').innerHTML=heading('Does the WISE argument make sense?','A critical reader’s view of the source cards, with questions for you to resolve.')+`<section class="card"><p>${esc(r.scope)}</p><p><strong>${r.reviewed} / ${r.total} cards reviewed</strong> · ${esc(r.date)} · Includes ${r.cards.filter(c=>c.verdict==='clear').length} cards that read clearly and ${r.cards.filter(c=>c.verdict==='not_prose').length} non-prose cards.</p><div class="actions"><a class="btn secondary" href="/api/guides/reader-review">Download revision priorities</a><a class="btn secondary" href="/api/guides/card-reviews">Download all card reviews</a><a class="btn secondary" href="/api/guides/wise-card-language">Download updated language-support audit</a></div><p class="tiny">This checks the imported card snapshot. Later vault edits are not automatically imported. Reviews are marked stale when their hash differs from the imported card.</p><div class="catalogue-filters"><label class="field">Find a card or idea<input type="search" id="reader-query" placeholder="e.g. ownership, denominator, I-wise…"></label><label class="field">Section<select id="reader-section"><option value="">All sections</option>${[...new Set(r.cards.map(c=>c.section))].sort().map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label class="field">Reader assessment<select id="reader-verdict"><option value="">All assessments</option>${Object.entries(verdicts).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label><label class="checkbox-row"><input type="checkbox" id="reader-used">Only marked as used in the archive</label><label class="checkbox-row"><input type="checkbox" id="reader-major">Only cards with a major question</label></div><p id="reader-count" role="status"></p></section><div id="reader-results" class="grid catalogue-grid"></div><div class="actions"><button class="btn secondary" id="reader-prev">Previous</button><span id="reader-page"></span><button class="btn secondary" id="reader-next">Next</button></div>`;
  function draw(){const q=$('#reader-query').value.toLowerCase(),section=$('#reader-section').value,v=$('#reader-verdict').value;const matches=r.cards.filter(c=>(!q||[c.card_id,c.title,c.intended_meaning,c.reader_question].join(' ').toLowerCase().includes(q))&&(!section||c.section===section)&&(!v||c.verdict===v)&&(!$('#reader-used').checked||c.in_paper)&&(!$('#reader-major').checked||c.major_count));const pages=Math.max(1,Math.ceil(matches.length/24));page=Math.min(page,pages-1);$('#reader-count').textContent=matches.length+' matching cards';$('#reader-page').textContent=`Page ${page+1} of ${pages}`;$('#reader-prev').disabled=page===0;$('#reader-next').disabled=page===pages-1;$('#reader-results').innerHTML=matches.slice(page*24,page*24+24).map(c=>`<a class="card catalogue-card" href="#reader/${encodeURIComponent(c.card_id)}"><span class="tag neutral">${esc(verdicts[c.verdict]||'Not reviewed')}</span><h3>${esc(c.card_id)}</h3><p>${esc(c.intended_meaning)}</p>${c.reader_question?`<p class="tiny">Reader asks: ${esc(c.reader_question)}</p>`:''}<small>${c.finding_count} specific points · ${c.in_paper?'marked as used':'alternative'}</small></a>`).join('')||'<p>No matching cards. Try fewer filters.</p>'}
  ['reader-query','reader-section','reader-verdict','reader-used','reader-major'].forEach(id=>$('#'+id).oninput=()=>{page=0;draw()});$('#reader-prev').onclick=()=>{page--;draw()};$('#reader-next').onclick=()=>{page++;draw()};draw();
 }
 async function comments(id,serial){
  const reports=await api('/wording-flags');if(!isCurrent(serial))return;
  $('#main').innerHTML=heading('My comments','Questions about wording, exercise instructions and the argument.', '<a class="btn secondary" href="/api/wording-flags-export">Download comments</a>')+`<section class="card"><p>Use “Flag unclear wording” at the top of any page. Selecting text is optional: you can paste or describe it. Comments are saved locally and included in backups.</p><button class="btn" id="new-flag">Add a comment</button></section>`+[...reports].reverse().map(r=>`<section class="card"><span class="tag neutral">${esc(r.status)}</span><p>${r.context.startsWith('#')?`<a href="${esc(r.context)}">Open the page this refers to</a>`:esc(r.context)}</p>${r.quote?`<blockquote class="prose">${esc(r.quote)}</blockquote>`:''}<p class="prose">${esc(r.comment)}</p><small>${new Date(r.created).toLocaleString()}</small><div class="actions"><button class="btn secondary" data-resolve-flag="${esc(r.id)}" data-status="${r.status==='open'?'resolved':'open'}">${r.status==='open'?'Mark resolved':'Reopen'}</button></div></section>`).join('');
  $('#new-flag').onclick=()=>flag();document.querySelectorAll('[data-resolve-flag]').forEach(b=>b.onclick=async()=>{try{await api('/wording-flags/'+b.dataset.resolveFlag,{status:b.dataset.status},'PATCH');if(isCurrent(serial))await comments(id,serial)}catch(e){toast(e.message)}});
 }
 return {enhancePractice,toolbox,reader,comments,flag,bindFlagButton,reviewHTML,phrasebook:phrasebook.render,mountPhrasebook:phrasebook.mount};
}
